import sys, os
from widgets import Widget


class TermChat:

    width = os.get_terminal_size().columns
    height = os.get_terminal_size().lines

    widgets: Widget = Widget()

    def __init__(self):
        # clean evything in the terminal and render the screen
        os.system('cls' if os.name == 'nt' else 'clear')

        screen = self.render_screen()
        print(screen)

    def render_screen(self):
        # render the screen
        screen = ""
        if len(self.widgets) > 0:
            for widget in self.widgets:
                screen += widget
        else:
            screen += ""
        return screen

    async def on_key_press(self):
        # get the key pressed by the user and handle it
        key = sys.stdin.read(1)
        return key.__str__()

    def run(self):
        # run the app
        while self.on_key_press() != 'q':
            print(self.render_screen())

class Widget:

    childers = []

    def __init__(self, parent=None):
        self.parent = parent

    def add_child(self, child):
        self.childers.append(child)

    def render(self):
        if len(self.childers) > 0:
            auxi = ""
            for child in self.childers:
                auxi += child.__str__()
            return auxi
        else:
            return ""

from __future__ import annotations

import asyncio

from textual.app import App, ComposeResult
from textual.binding import Binding
from textual.containers import Container
from textual.widgets import Input, Static

from agent.config import AppConfig, load_config
from agent.ollama_client import ModelInfo, OllamaClient
from UI.widgets import ChatEntry, ModelSummary, PromptInput, StatusLine, TranscriptView


class TermChatApp(App[None]):
    TITLE = "TermChat"
    SUB_TITLE = "Local Ollama assistant"
    CSS = """
    Screen {
        background: transparent;
    }

    #shell {
        width: 100%;
        height: 100%;
        padding: 1 2;
        background: transparent;
    }

    #panel {
        width: 100%;
        height: 100%;
        layout: vertical;
        padding: 1 2;
        border: round #7aa2f7;
        background: #0f172a 24%;
    }

    #title {
        height: auto;
        text-style: bold;
        color: #e2e8f0;
        margin-bottom: 1;
    }

    #model_summary {
        height: auto;
        color: #93c5fd;
        margin-bottom: 1;
    }

    #transcript {
        height: 1fr;
        border: round #334155;
        background: transparent;
        padding: 1 1;
        scrollbar-background: transparent;
    }

    #prompt {
        margin-top: 1;
    }

    #status {
        height: auto;
        color: #94a3b8;
        margin-top: 1;
    }
    """
    BINDINGS = [
        Binding("ctrl+q", "quit", "Quit"),
        Binding("ctrl+r", "reload_models", "Reload models"),
        Binding("ctrl+s", "toggle_stream", "Toggle stream"),
        Binding("f2", "cycle_model", "Next model"),
    ]

    def __init__(self, config: AppConfig | None = None) -> None:
        super().__init__()
        self.config = config or load_config()
        self.client = OllamaClient(self.config)
        self.entries: list[ChatEntry] = []
        self.models: list[ModelInfo] = []
        self.current_model = self.config.ollama.model
        self._active_task: asyncio.Task[None] | None = None

    def compose(self) -> ComposeResult:
        with Container(id="shell"):
            with Container(id="panel"):
                yield Static("TermChat", id="title")
                yield ModelSummary(id="model_summary")
                yield TranscriptView(id="transcript")
                yield PromptInput()
                yield StatusLine(id="status")

    async def on_mount(self) -> None:
        panel = self.query_one("#panel")
        panel.styles.background = f"#0f172a {self.config.ui.panel_opacity}%"
        await self._refresh_models()
        self._refresh_views("Listo. Escribe un mensaje para empezar.")
        self.query_one(PromptInput).focus()

    async def on_input_submitted(self, event: Input.Submitted) -> None:
        if event.input.id != "prompt":
            return

        prompt = event.value.strip()
        if not prompt:
            return

        event.input.value = ""
        self.entries.append(ChatEntry(role="user", content=prompt))
        self.entries.append(ChatEntry(role="assistant", content=""))
        self._refresh_views("Consultando Ollama...")

        if self._active_task and not self._active_task.done():
            self._active_task.cancel()

        self._active_task = asyncio.create_task(self._handle_prompt())

    async def _handle_prompt(self) -> None:
        history = self._build_messages()
        try:
            if self.config.ollama.stream:
                answer = await self._stream_response(history)
            else:
                answer = await self.client.complete(history, model=self.current_model)

            self.entries[-1] = ChatEntry(role="assistant", content=answer)
            self._refresh_views("Respuesta recibida.")
        except asyncio.CancelledError:
            self._set_status("Solicitud cancelada.")
            raise
        except Exception as exc:
            if self.entries and self.entries[-1].role == "assistant" and not self.entries[-1].content:
                self.entries.pop()
            self._set_status(f"Error de Ollama: {exc}")
            self.notify(str(exc), severity="error")
        finally:
            self._active_task = None

    async def _stream_response(self, history: list[dict[str, str]]) -> str:
        tokens: list[str] = []
        async for chunk in self.client.stream_chat(history, model=self.current_model):
            tokens.append(chunk)
            self.entries[-1] = ChatEntry(role="assistant", content="".join(tokens))
            self._refresh_views("Recibiendo streaming...")
        return "".join(tokens)

    async def _refresh_models(self) -> None:
        try:
            self.models = await self.client.list_models()
            if self.models and self.current_model not in {model.name for model in self.models}:
                self.current_model = self.models[0].name
            self._set_status(f"{len(self.models)} modelo(s) disponibles en Ollama.")
        except Exception as exc:
            self.models = []
            self._set_status(f"No se pudo consultar Ollama: {exc}")

    def action_reload_models(self) -> None:
        asyncio.create_task(self._refresh_models())

    def action_toggle_stream(self) -> None:
        self.config.ollama.stream = not self.config.ollama.stream
        mode = "activado" if self.config.ollama.stream else "desactivado"
        self._set_status(f"Streaming {mode}.")

    def action_cycle_model(self) -> None:
        if not self.models:
            self._set_status("No hay modelos cargados.")
            return

        names = [model.name for model in self.models]
        if self.current_model not in names:
            self.current_model = names[0]
        else:
            index = names.index(self.current_model)
            self.current_model = names[(index + 1) % len(names)]
        self._refresh_views(f"Modelo activo: {self.current_model}")

    def _build_messages(self) -> list[dict[str, str]]:
        messages: list[dict[str, str]] = [{"role": "system", "content": self.config.assistant.system_prompt}]
        for entry in self.entries[-self.config.history_limit :]:
            if entry.content:
                messages.append({"role": entry.role, "content": entry.content})
        return messages

    def _refresh_views(self, status: str) -> None:
        self.query_one(TranscriptView).set_entries(self.entries)
        self.query_one(ModelSummary).set_state(
            model=self.current_model,
            host=self.config.ollama.host,
            stream=self.config.ollama.stream,
            available=len(self.models),
        )
        self._set_status(status)

    def _set_status(self, message: str) -> None:
        self.query_one(StatusLine).set_message(message)


def run() -> None:
    TermChatApp().run()

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
import os
import tomllib
from typing import Any


def _default_ollama_host() -> str:
    return os.environ.get("OLLAMA_HOST", "http://localhost:11434")


def _default_model() -> str:
    return os.environ.get("OLLAMA_MODEL", "llama3.1")


@dataclass(slots=True)
class OllamaConfig:
    host: str = field(default_factory=_default_ollama_host)
    model: str = field(default_factory=_default_model)
    stream: bool = True


@dataclass(slots=True)
class UIConfig:
    panel_opacity: int = 24
    accent: str = "#7aa2f7"
    transparent_background: bool = True


@dataclass(slots=True)
class AssistantConfig:
    system_prompt: str = (
        "You are TermChat, a concise local terminal assistant. "
        "Prioritize actionable responses, short explanations, and safe defaults."
    )
    mode: str = "default"
    skills: list[str] = field(default_factory=list)
    rules: list[str] = field(default_factory=list)
    context_files: list[str] = field(default_factory=list)


@dataclass(slots=True)
class AppConfig:
    ollama: OllamaConfig = field(default_factory=OllamaConfig)
    ui: UIConfig = field(default_factory=UIConfig)
    assistant: AssistantConfig = field(default_factory=AssistantConfig)
    history_limit: int = 24

    @classmethod
    def load(cls, path: Path | None = None) -> "AppConfig":
        config = cls()
        for candidate in _config_candidates(path):
            if candidate.exists():
                data = tomllib.loads(candidate.read_text(encoding="utf-8"))
                config.apply(data)
        return config

    def apply(self, data: dict[str, Any]) -> None:
        ollama = data.get("ollama", {})
        if isinstance(ollama, dict):
            self.ollama.host = str(ollama.get("host", self.ollama.host))
            self.ollama.model = str(ollama.get("model", self.ollama.model))
            self.ollama.stream = bool(ollama.get("stream", self.ollama.stream))

        ui = data.get("ui", {})
        if isinstance(ui, dict):
            self.ui.panel_opacity = int(ui.get("panel_opacity", self.ui.panel_opacity))
            self.ui.accent = str(ui.get("accent", self.ui.accent))
            self.ui.transparent_background = bool(ui.get("transparent_background", self.ui.transparent_background))

        assistant = data.get("assistant", {})
        if isinstance(assistant, dict):
            self.assistant.system_prompt = str(assistant.get("system_prompt", self.assistant.system_prompt))
            self.assistant.mode = str(assistant.get("mode", self.assistant.mode))
            self.assistant.skills = _normalize_list(assistant.get("skills", self.assistant.skills))
            self.assistant.rules = _normalize_list(assistant.get("rules", self.assistant.rules))
            self.assistant.context_files = _normalize_list(assistant.get("context_files", self.assistant.context_files))

        if "history_limit" in data:
            self.history_limit = int(data["history_limit"])


def load_config(path: Path | None = None) -> AppConfig:
    return AppConfig.load(path)


def _config_candidates(path: Path | None) -> list[Path]:
    if path is not None:
        return [path]

    repo_root = Path(__file__).resolve().parents[2]
    user_config = Path.home() / ".config" / "termchat" / "config.toml"
    return [repo_root / "config" / "termchat.toml", user_config]


def _normalize_list(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, list):
        return [str(item) for item in value]
    if isinstance(value, tuple):
        return [str(item) for item in value]
    return [str(value)]

