class TermChatApp(App[None]):
    TITLE = "TermChat"
    SUB_TITLE = "Local Ollama assistant"
    CSS = """
    Screen {
        background: transparent;
    }

    #shell {
        width: 100%;
        height: 100%;
        padding: 1 2;
        background: transparent;
    }

    #panel {
        width: 100%;
        height: 100%;
        layout: vertical;
        padding: 1 2;
        border: round #7aa2f7;
        background: #0f172a 24%;
    }

    #title {
        height: auto;
        text-style: bold;
        color: #e2e8f0;
        margin-bottom: 1;
